144	        pet.setOwner(this);
145	    }
146	
147	    /**
148	     * Return the Pet with the given name, or null if none found for this Owner.
149	     *
150	     * @param name to test
151	     * @return true if pet name is already in use
152	     */
153	    public Pet getPet(String name) {
154	        return getPet(name, false);
155	    }
156	
157	    /**
158	     * Return the Pet with the given name, or null if none found for this Owner.
159	     *
160	     * @param name to test
161	     * @return true if pet name is already in use
162	     */
163	    public Pet getPet(String name, boolean ignoreNew) {
164	        name = name.toLowerCase();
165	        for (Pet pet : getPetsInternal()) {
166	            if (!ignoreNew || !pet.isNew()) {
167	                String compName = pet.getName();
168	                compName = compName.toLowerCase();
169	                if (compName.equals(name)) {
170	                    return pet;
171	                }
172	            }
173	        }
174	        return null;
175	    }
176	
177	    public Pet getPet(Integer petId) {
178	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
179	    }
