181	    @Override
182	    public String toString() {
183	        return new ToStringCreator(this)
184	
185	            .append("id", this.getId())
186	            .append("new", this.isNew())
187	            .append("lastName", this.getLastName())
188	            .append("firstName", this.getFirstName())
189	            .append("address", this.address)
190	            .append("city", this.city)
191	            .append("telephone", this.telephone)
192	            .toString();
193	    }
194	}
