9	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
10	        String city3 = prefix3(owner.getCity());
11	        String last3 = prefix3(owner.getLastName());
12	        int sequence = countInCity(ownerRepository, owner.getCity()) + 1;
13	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
14	    }
15	
16	    private static String prefix3(String value) {
17	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
18	    }
19	
20	    private static int countInCity(OwnerRepository ownerRepository, String city) {
21	        int count = 0;
22	        for (Owner other : ownerRepository.findAll()) {
23	            if (city.equals(other.getCity())) {
24	                count++;
25	            }
26	        }
27	        return count;
28	    }
29	}
